using Dapper;
using Npgsql;
using Sigov.Application.Common;
using Sigov.Application.ComprasEmpresariais;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.ComprasEmpresariais;

public sealed class FornecedorRepository(NpgsqlConnectionFactory factory):IFornecedorRepository
{
 public async Task<PagedResult<FornecedorResumo>> ListarAsync(Guid t,FornecedorFiltro f,CancellationToken ct){var p=Math.Max(1,f.Pagina);var s=Math.Clamp(f.Tamanho,1,100);const string q="select count(*) from sigov.compras_empresarial_fornecedor where tenant_id=@t and not is_deleted and (@status is null or status=@status) and (@busca is null or razao_social ilike @term or nome_fantasia ilike @term or codigo ilike @term);select id,codigo,razao_social RazaoSocial,nome_fantasia NomeFantasia,documento_mascarado DocumentoMascarado,status,score,version from sigov.compras_empresarial_fornecedor where tenant_id=@t and not is_deleted and (@status is null or status=@status) and (@busca is null or razao_social ilike @term or nome_fantasia ilike @term or codigo ilike @term) order by razao_social offset @off limit @s";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,status=string.IsNullOrWhiteSpace(f.Status)?null:f.Status.ToUpperInvariant(),busca=string.IsNullOrWhiteSpace(f.Busca)?null:f.Busca,term=$"%{f.Busca}%",off=(p-1)*s,s},cancellationToken:ct));var n=await m.ReadSingleAsync<long>();return new((await m.ReadAsync<FornecedorResumo>()).AsList(),p,s,n);}
 public async Task<FornecedorResumo?> ObterAsync(Guid t,Guid id,CancellationToken ct){const string q="select id,codigo,razao_social RazaoSocial,nome_fantasia NomeFantasia,documento_mascarado DocumentoMascarado,status,score,version from sigov.compras_empresarial_fornecedor where tenant_id=@t and id=@id and not is_deleted";await using var c=factory.CreateConnection();return await c.QuerySingleOrDefaultAsync<FornecedorResumo>(new CommandDefinition(q,new{t,id},cancellationToken:ct));}
 public async Task<Guid> CriarAsync(ComprasContext x,CriarFornecedorRequest r,string key,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var old=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select recurso_id from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='FORNECEDOR_CRIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(old.HasValue){await tx.CommitAsync(ct);return old.Value;}var id=Guid.NewGuid();var codigo=await Next(c,tx,x.TenantId,"FORNECEDOR","FOR",ct);const string sql="insert into sigov.compras_empresarial_fornecedor(id,tenant_id,codigo,tipo_pessoa,documento_hash,documento_mascarado,razao_social,nome_fantasia,categoria,porte,condicao_pagamento,prazo_medio,observacoes,created_by,updated_by,correlation_id) values(@id,@t,@codigo,upper(@TipoPessoa),encode(digest(regexp_replace(@Documento,'[^0-9]','','g'),'sha256'),'hex'),case when length(regexp_replace(@Documento,'[^0-9]','','g'))=14 then '***.***.***/' || substring(regexp_replace(@Documento,'[^0-9]','','g') from 9 for 4) || '-**' else '***.***.' || substring(regexp_replace(@Documento,'[^0-9]','','g') from 7 for 3) || '-**' end,@RazaoSocial,@NomeFantasia,@Categoria,@Porte,@CondicaoPagamento,@PrazoMedio,@Observacoes,@us,@us,@corr);insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'FORNECEDOR',@id,'CRIADO',@us,@corr);insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id) values(@t,'FORNECEDOR_CRIAR',@key,@id);insert into sigov.integracao_outbox(id,tenant_id,tipo_evento,aggregate_id,payload,created_at) values(gen_random_uuid(),@t,'compras.fornecedor.criado',@id,jsonb_build_object('fornecedorId',@id),now())";await c.ExecuteAsync(new CommandDefinition(sql,new{id,t=x.TenantId,codigo,r.TipoPessoa,r.Documento,r.RazaoSocial,r.NomeFantasia,r.Categoria,r.Porte,r.CondicaoPagamento,r.PrazoMedio,r.Observacoes,us=x.UsuarioId.ToString(),corr=x.CorrelationId,key},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
 public async Task AlterarStatusAsync(ComprasContext x,Guid id,AlterarStatusRequest r,CancellationToken ct){var status=r.Status.ToUpperInvariant();if((status is "BLOQUEADO" or "SUSPENSO") && string.IsNullOrWhiteSpace(r.Motivo))throw new ArgumentException("Motivo obrigatório.");await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var n=await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_fornecedor set status=@status,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version and not is_deleted",new{t=x.TenantId,id,status,r.Version,r.Motivo,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));if(n!=1)throw new InvalidOperationException("Fornecedor não encontrado ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'FORNECEDOR',@id,@status,jsonb_build_object('motivo',@motivo),@us,@corr)",new{t=x.TenantId,id,status,motivo=r.Motivo,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await tx.CommitAsync(ct);}
 public Task AdicionarContatoAsync(ComprasContext x,Guid id,AdicionarContatoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"CONTATO","insert into sigov.compras_empresarial_fornecedor_contato(id,tenant_id,fornecedor_id,nome,email,telefone,principal,created_by,updated_by,correlation_id) values(@child,@t,@id,@Nome,@Email,@Telefone,@Principal,@us,@us,@corr)",r,ct);
 public Task AdicionarEnderecoAsync(ComprasContext x,Guid id,AdicionarEnderecoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"ENDERECO","insert into sigov.compras_empresarial_fornecedor_endereco(id,tenant_id,fornecedor_id,tipo,logradouro,numero,complemento,bairro,cidade,uf,cep,created_by,updated_by,correlation_id) values(@child,@t,@id,@Tipo,@Logradouro,@Numero,@Complemento,@Bairro,@Cidade,upper(@Uf),@Cep,@us,@us,@corr)",r,ct);
 public Task AdicionarDocumentoAsync(ComprasContext x,Guid id,AdicionarDocumentoRequest r,string key,CancellationToken ct)=>Child(x,id,key,"DOCUMENTO","insert into sigov.compras_empresarial_fornecedor_documento(id,tenant_id,fornecedor_id,documento_ged_id,tipo,obrigatorio,validade,created_by,updated_by,correlation_id) values(@child,@t,@id,@DocumentoGedId,@Tipo,@Obrigatorio,@Validade,@us,@us,@corr)",r,ct);
 private async Task Child(ComprasContext x,Guid id,string key,string op,string sql,object values,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var args=new DynamicParameters(values);args.Add("child",Guid.NewGuid());args.Add("t",x.TenantId);args.Add("id",id);args.Add("us",x.UsuarioId.ToString());args.Add("corr",x.CorrelationId);args.Add("key",key);args.Add("op",op);var n=await c.ExecuteAsync(new CommandDefinition(sql+";insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id) values(@t,@op,@key,@child) on conflict do nothing;insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'FORNECEDOR',@id,@op,@us,@corr)",args,tx,cancellationToken:ct));if(n!=3)throw new InvalidOperationException("Operação duplicada ou fornecedor inválido.");await tx.CommitAsync(ct);}
 internal static async Task<string> Next(NpgsqlConnection c,NpgsqlTransaction tx,Guid t,string tipo,string prefix,CancellationToken ct){var n=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.compras_empresarial_numeracao(tenant_id,tipo,ano,ultimo_numero) values(@t,@tipo,extract(year from current_date)::int,1) on conflict(tenant_id,tipo,ano) do update set ultimo_numero=sigov.compras_empresarial_numeracao.ultimo_numero+1,updated_at=now() returning ultimo_numero",new{t,tipo},tx,cancellationToken:ct));return $"{prefix}-{DateTime.UtcNow:yyyy}-{n:000000}";}
}

public sealed class RequisicaoCompraRepository(NpgsqlConnectionFactory factory):IRequisicaoCompraRepository
{
 public async Task<PagedResult<RequisicaoResumo>> ListarAsync(Guid t,RequisicaoFiltro f,CancellationToken ct)
 {
  var p=Math.Max(1,f.Pagina);
  var s=Math.Clamp(f.Tamanho,1,100);
  var status=string.IsNullOrWhiteSpace(f.Status)?null:f.Status.Trim().ToUpperInvariant();
  var busca=string.IsNullOrWhiteSpace(f.Busca)?null:f.Busca.Trim();
  var order=((f.OrdenarPor??"data").Trim().ToLowerInvariant(),(f.Direcao??"desc").Trim().ToLowerInvariant()) switch
  {
   ("numero","asc")=>"r.numero asc, r.id asc",
   ("numero",_)=>"r.numero desc, r.id desc",
   ("status","asc")=>"r.status asc, r.id asc",
   ("status",_)=>"r.status desc, r.id desc",
   ("data","asc")=>"r.created_at asc, r.id asc",
   _=>"r.created_at desc, r.id desc"
  };
  var sql=$@"
select count(*)
from sigov.compras_empresarial_requisicao r
where r.tenant_id=@t and not r.is_deleted
 and (@status is null or r.status=@status)
 and (@busca is null or r.numero ilike @term or r.justificativa ilike @term)
 and (@inicio is null or r.created_at>=@inicio)
 and (@fim is null or r.created_at<(@fim::date+1));
select r.id,r.numero,r.status,r.valor_estimado ValorEstimado,r.data_necessaria DataNecessaria,
 r.created_at DataSolicitacao,
 case when r.ordem_servico_id is not null then 'Ordem de serviço'
      when r.projeto_id is not null then 'Projeto'
      when r.contrato_id is not null then 'Contrato'
      when r.almoxarifado_id is not null then 'Almoxarifado'
      else 'Solicitação direta' end Origem,
 count(i.id)::int Itens,r.version
from sigov.compras_empresarial_requisicao r
left join sigov.compras_empresarial_requisicao_item i
 on i.tenant_id=r.tenant_id and i.requisicao_id=r.id and not i.is_deleted
where r.tenant_id=@t and not r.is_deleted
 and (@status is null or r.status=@status)
 and (@busca is null or r.numero ilike @term or r.justificativa ilike @term)
 and (@inicio is null or r.created_at>=@inicio)
 and (@fim is null or r.created_at<(@fim::date+1))
group by r.id
order by {order}
offset @off limit @s";
  var args=new{t,status,busca,term=$"%{busca}%",inicio=f.DataInicial,fim=f.DataFinal,off=(long)(p-1)*s,s};
  await using var c=factory.CreateConnection();
  using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,args,cancellationToken:ct));
  var total=await m.ReadSingleAsync<long>();
  return new((await m.ReadAsync<RequisicaoResumo>()).AsList(),p,s,total);
 }
 public async Task<RequisicaoDetalhe?> ObterAsync(Guid t,Guid id,CancellationToken ct){const string q=@"select id,numero,status,setor,urgencia,data_necessaria DataNecessaria,justificativa,observacoes,valor_estimado ValorEstimado,version from sigov.compras_empresarial_requisicao where tenant_id=@t and id=@id and not is_deleted;
select id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado ValorEstimado,permite_parcial PermiteParcial,exige_inspecao ExigeInspecao from sigov.compras_empresarial_requisicao_item where tenant_id=@t and requisicao_id=@id and not is_deleted order by ordem,id;
select acao,detalhes::text Detalhes,created_at CriadoEm from sigov.compras_empresarial_historico where tenant_id=@t and aggregate_type='REQUISICAO' and aggregate_id=@id order by created_at,id";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<RequisicaoCabecalho>();if(h is null)return null;var itens=(await m.ReadAsync<RequisicaoItemDetalhe>()).AsList();var historico=(await m.ReadAsync<RequisicaoHistorico>()).AsList();return new(h.Id,h.Numero,h.Status,h.Setor,h.Urgencia,h.DataNecessaria,h.Justificativa,h.Observacoes,h.ValorEstimado,h.Version,itens,historico);}
 public async Task<Guid> CriarAsync(ComprasContext x,CriarRequisicaoRequest r,string key,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var old=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select recurso_id from sigov.compras_empresarial_idempotencia where tenant_id=@t and operacao='REQUISICAO_CRIAR' and chave=@key",new{t=x.TenantId,key},tx,cancellationToken:ct));if(old.HasValue){await tx.CommitAsync(ct);return old.Value;}var id=Guid.NewGuid();var numero=await FornecedorRepository.Next(c,tx,x.TenantId,"REQUISICAO","RC",ct);var total=r.Itens.Sum(i=>i.Quantidade*i.ValorEstimado);const string head="insert into sigov.compras_empresarial_requisicao(id,tenant_id,numero,solicitante_id,setor,centro_custo_id,projeto_id,contrato_id,ordem_servico_id,almoxarifado_id,urgencia,data_necessaria,justificativa,observacoes,valor_estimado,created_by,updated_by,correlation_id) values(@id,@t,@numero,@usId,@Setor,@CentroCustoId,@ProjetoId,@ContratoId,@OrdemServicoId,@AlmoxarifadoId,upper(@Urgencia),@DataNecessaria,@Justificativa,@Observacoes,@total,@us,@us,@corr)";await c.ExecuteAsync(new CommandDefinition(head,new{id,t=x.TenantId,numero,usId=x.UsuarioId,r.Setor,r.CentroCustoId,r.ProjetoId,r.ContratoId,r.OrdemServicoId,r.AlmoxarifadoId,r.Urgencia,r.DataNecessaria,r.Justificativa,r.Observacoes,total,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));var ordem=0;foreach(var item in r.Itens){ordem++;await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_requisicao_item(tenant_id,requisicao_id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado,permite_parcial,exige_inspecao,created_by,updated_by,correlation_id) values(@t,@id,@ordem,upper(@Tipo),@Descricao,@Especificacao,@Unidade,@Quantidade,@ValorEstimado,@PermiteParcial,@ExigeInspecao,@us,@us,@corr)",new{t=x.TenantId,id,ordem,item.Tipo,item.Descricao,item.Especificacao,item.Unidade,item.Quantidade,item.ValorEstimado,item.PermiteParcial,item.ExigeInspecao,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,created_by,correlation_id) values(@t,'REQUISICAO',@id,'RASCUNHO_CRIADO',@us,@corr);insert into sigov.compras_empresarial_idempotencia(tenant_id,operacao,chave,recurso_id) values(@t,'REQUISICAO_CRIAR',@key,@id)",new{t=x.TenantId,id,key,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
 public async Task AtualizarAsync(ComprasContext x,Guid id,AtualizarRequisicaoRequest r,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var total=r.Itens.Sum(i=>i.Quantidade*i.ValorEstimado);const string update="update sigov.compras_empresarial_requisicao set setor=@Setor,centro_custo_id=@CentroCustoId,projeto_id=@ProjetoId,contrato_id=@ContratoId,ordem_servico_id=@OrdemServicoId,almoxarifado_id=@AlmoxarifadoId,urgencia=upper(@Urgencia),data_necessaria=@DataNecessaria,justificativa=@Justificativa,observacoes=@Observacoes,valor_estimado=@total,version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version and status='RASCUNHO' and not is_deleted";var args=new{t=x.TenantId,id,r.Setor,r.CentroCustoId,r.ProjetoId,r.ContratoId,r.OrdemServicoId,r.AlmoxarifadoId,r.Urgencia,r.DataNecessaria,r.Justificativa,r.Observacoes,total,r.Version,us=x.UsuarioId.ToString(),corr=x.CorrelationId};if(await c.ExecuteAsync(new CommandDefinition(update,args,tx,cancellationToken:ct))!=1)throw new InvalidOperationException("Requisição fora de rascunho ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("update sigov.compras_empresarial_requisicao_item set is_deleted=true,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and requisicao_id=@id and not is_deleted",args,tx,cancellationToken:ct));var ordem=0;foreach(var item in r.Itens){ordem++;const string upsert="insert into sigov.compras_empresarial_requisicao_item(tenant_id,requisicao_id,ordem,tipo,descricao,especificacao,unidade,quantidade,valor_estimado,permite_parcial,exige_inspecao,created_by,updated_by,correlation_id) values(@t,@id,@ordem,upper(@Tipo),@Descricao,@Especificacao,@Unidade,@Quantidade,@ValorEstimado,@PermiteParcial,@ExigeInspecao,@us,@us,@corr) on conflict(tenant_id,requisicao_id,ordem) do update set tipo=excluded.tipo,descricao=excluded.descricao,especificacao=excluded.especificacao,unidade=excluded.unidade,quantidade=excluded.quantidade,valor_estimado=excluded.valor_estimado,permite_parcial=excluded.permite_parcial,exige_inspecao=excluded.exige_inspecao,is_deleted=false,updated_at=now(),updated_by=excluded.updated_by,correlation_id=excluded.correlation_id,version=sigov.compras_empresarial_requisicao_item.version+1";await c.ExecuteAsync(new CommandDefinition(upsert,new{t=x.TenantId,id,ordem,item.Tipo,item.Descricao,item.Especificacao,item.Unidade,item.Quantidade,item.ValorEstimado,item.PermiteParcial,item.ExigeInspecao,us=x.UsuarioId.ToString(),corr=x.CorrelationId},tx,cancellationToken:ct));}await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'REQUISICAO',@id,'RASCUNHO_ATUALIZADO',jsonb_build_object('versao_anterior',@Version),@us,@corr)",args,tx,cancellationToken:ct));await tx.CommitAsync(ct);}
 public async Task EnviarAsync(ComprasContext x,Guid id,long version,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);const string q="update sigov.compras_empresarial_requisicao r set status='PENDENTE_APROVACAO',version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@version and status='RASCUNHO' and exists(select 1 from sigov.compras_empresarial_requisicao_item i where i.tenant_id=r.tenant_id and i.requisicao_id=r.id and not i.is_deleted)";var args=new{t=x.TenantId,id,version,us=x.UsuarioId.ToString(),corr=x.CorrelationId};var n=await c.ExecuteAsync(new CommandDefinition(q,args,tx,cancellationToken:ct));if(n!=1)throw new InvalidOperationException("Requisição sem itens, fora de rascunho ou versão desatualizada.");await c.ExecuteAsync(new CommandDefinition("insert into sigov.compras_empresarial_historico(tenant_id,aggregate_type,aggregate_id,acao,detalhes,created_by,correlation_id) values(@t,'REQUISICAO',@id,'ENVIADA_PARA_APROVACAO',jsonb_build_object('versao_analisada',@version),@us,@corr)",args,tx,cancellationToken:ct));await tx.CommitAsync(ct);}
 private sealed record RequisicaoCabecalho(Guid Id,string Numero,string Status,string? Setor,string Urgencia,DateOnly? DataNecessaria,string Justificativa,string? Observacoes,decimal ValorEstimado,long Version);
}
public sealed class ComprasDashboardRepository(NpgsqlConnectionFactory factory):IComprasDashboardRepository
{public async Task<ComprasDashboard> ObterAsync(Guid t,CancellationToken ct){const string q="select coalesce(sum(valor_estimado),0) TotalSolicitado,coalesce(sum(valor_estimado) filter(where status in('APROVADA','EM_COTACAO','PEDIDA','RECEBIDA','ENCERRADA')),0) ValorAprovado,(select count(*) from sigov.compras_empresarial_aprovacao where tenant_id=@t and status='PENDENTE')::int AprovacoesPendentes,(select count(*) from sigov.compras_empresarial_cotacao where tenant_id=@t and status in('ABERTA','EM_RESPOSTA'))::int CotacoesAbertas,(select count(*) from sigov.compras_empresarial_pedido where tenant_id=@t and previsao<current_date and status not in('RECEBIDO','ENCERRADO','CANCELADO'))::int PedidosAtrasados,(select count(*) from sigov.compras_empresarial_pedido where tenant_id=@t and status in('CONFIRMADO','PARCIALMENTE_RECEBIDO'))::int RecebimentosPendentes,(select count(*) from sigov.compras_empresarial_fatura where tenant_id=@t and status='BLOQUEADA')::int FaturasBloqueadas,(select count(*) from sigov.compras_empresarial_fornecedor_documento where tenant_id=@t and validade between current_date and current_date+30 and not is_deleted)::int DocumentosVencendo from sigov.compras_empresarial_requisicao where tenant_id=@t and not is_deleted";await using var c=factory.CreateConnection();return await c.QuerySingleAsync<ComprasDashboard>(new CommandDefinition(q,new{t},cancellationToken:ct));}}

public sealed class RecebimentoCompraRepository(NpgsqlConnectionFactory factory):IRecebimentoCompraRepository
{
 public async Task<CentralRecebimentos> ListarAsync(Guid t,RecebimentoFiltro f,CancellationToken ct)
 {
  var page=Math.Max(1,f.Pagina);var size=Math.Clamp(f.Tamanho,1,100);
  const string where=@"r.tenant_id=@t and (@fornecedor is null or fo.razao_social ilike @termFornecedor or fo.nome_fantasia ilike @termFornecedor) and (@pedido is null or p.numero ilike @termPedido) and (@status is null or r.status=@status) and (@almox is null or r.almoxarifado_id=@almox) and (@responsavel is null or r.created_by ilike @termResponsavel) and (@inicio is null or r.data_operacao>=@inicio) and (@fim is null or r.data_operacao<(@fim::date+1))";
  var sql=$@"select count(*) from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id where {where};
select r.id,r.pedido_id PedidoId,p.numero PedidoNumero,coalesce(fo.nome_fantasia,fo.razao_social) FornecedorNome,r.status,r.documento,a.nome AlmoxarifadoNome,r.created_at CriadoEm,r.created_by Responsavel,count(ri.id) filter(where ri.quantidade_rejeitada>0)::int Divergencias from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id join sigov.estoque_almoxarifado a on a.id=r.almoxarifado_id and a.tenant_id=r.tenant_id left join sigov.compras_empresarial_recebimento_item ri on ri.recebimento_id=r.id and ri.tenant_id=r.tenant_id where {where} group by r.id,p.id,fo.id,a.id order by r.created_at desc,r.id desc offset @off limit @size;
select (select count(*) from sigov.compras_empresarial_pedido p where p.tenant_id=@t and p.status in('CONFIRMADO','PARCIALMENTE_RECEBIDO') and not p.is_deleted) Aptos,count(*) filter(where r.status='EM_CONFERENCIA') EmConferencia,count(*) filter(where r.status='CONCLUIDO') Concluidos,count(*) filter(where exists(select 1 from sigov.compras_empresarial_recebimento_item x where x.tenant_id=r.tenant_id and x.recebimento_id=r.id and x.quantidade_rejeitada>0)) Divergencias from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor fo on fo.id=p.fornecedor_id and fo.tenant_id=p.tenant_id where {where}";
  var args=new{t,fornecedor=Clean(f.Fornecedor),termFornecedor=$"%{Clean(f.Fornecedor)}%",pedido=Clean(f.Pedido),termPedido=$"%{Clean(f.Pedido)}%",status=Clean(f.Status)?.ToUpperInvariant(),almox=f.AlmoxarifadoId,responsavel=Clean(f.Responsavel),termResponsavel=$"%{Clean(f.Responsavel)}%",inicio=f.DataInicial,fim=f.DataFinal,off=(page-1)*size,size};
  await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,args,cancellationToken:ct));var total=await m.ReadSingleAsync<long>();var items=(await m.ReadAsync<RecebimentoResumo>()).AsList();var totals=await m.ReadSingleAsync<RecebimentoTotais>();return new(new(items,page,size,total),totals);
 }
 public async Task<PedidoParaRecebimento?> ObterPedidoAsync(Guid t,Guid id,CancellationToken ct)
 {
  const string sql=@"select p.id,p.numero,p.status,p.fornecedor_id FornecedorId,coalesce(f.nome_fantasia,f.razao_social) Fornecedor,p.version from sigov.compras_empresarial_pedido p join sigov.compras_empresarial_fornecedor f on f.id=p.fornecedor_id and f.tenant_id=p.tenant_id where p.tenant_id=@t and p.id=@id and not p.is_deleted;
select i.id,i.produto_id ProdutoId,pr.nome Produto,pr.unidade,i.quantidade QuantidadePedida,i.quantidade_cancelada QuantidadeCancelada,coalesce(sum(ri.quantidade_fisica),0) QuantidadeFisica,coalesce(sum(ri.quantidade_aceita),0) QuantidadeAceita,coalesce(sum(ri.quantidade_rejeitada),0) QuantidadeRejeitada,coalesce(sum(ri.quantidade_conferencia),0) QuantidadeEmConferencia,(i.quantidade-i.quantidade_cancelada-coalesce(sum(ri.quantidade_fisica),0)) QuantidadePendente,i.exige_inspecao ExigeInspecao from sigov.compras_empresarial_pedido_item i join sigov.estoque_produto pr on pr.id=i.produto_id and pr.tenant_id=i.tenant_id left join sigov.compras_empresarial_recebimento_item ri on ri.pedido_item_id=i.id and ri.tenant_id=i.tenant_id where i.tenant_id=@t and i.pedido_id=@id group by i.id,pr.id order by i.id;
select id,nome from sigov.estoque_almoxarifado where tenant_id=@t and ativo order by nome,id";
  await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,new{t,id},cancellationToken:ct));var h=await m.ReadSingleOrDefaultAsync<PedidoHeader>();if(h is null)return null;var items=(await m.ReadAsync<PedidoRecebimentoItem>()).AsList();return new(h.Id,h.Numero,h.Status,h.FornecedorId,h.Fornecedor,h.Version,items,(await m.ReadAsync<AlmoxarifadoOpcao>()).AsList());
 }
 public async Task<RecebimentoDetalhe?> ObterAsync(Guid t,Guid id,CancellationToken ct)
 {
  const string sql=@"select r.id,r.pedido_id PedidoId,p.numero PedidoNumero,coalesce(f.nome_fantasia,f.razao_social) Fornecedor,r.documento,a.nome Almoxarifado,r.data_operacao DataOperacao,r.status,r.resultado_inspecao ResultadoInspecao,r.observacoes,r.version
from sigov.compras_empresarial_recebimento r join sigov.compras_empresarial_pedido p on p.id=r.pedido_id and p.tenant_id=r.tenant_id join sigov.compras_empresarial_fornecedor f on f.id=p.fornecedor_id and f.tenant_id=p.tenant_id join sigov.estoque_almoxarifado a on a.id=r.almoxarifado_id and a.tenant_id=r.tenant_id where r.tenant_id=@t and r.id=@id;
select ri.id,pr.nome Produto,pr.unidade,ri.quantidade_fisica QuantidadeFisica,ri.quantidade_aceita QuantidadeAceita,ri.quantidade_rejeitada QuantidadeRejeitada,ri.quantidade_conferencia QuantidadeConferencia,ri.lote,ri.validade,ri.numero_serie NumeroSerie from sigov.compras_empresarial_recebimento_item ri join sigov.estoque_produto pr on pr.id=ri.produto_id and pr.tenant_id=ri.tenant_id where ri.tenant_id=@t and ri.recebimento_id=@id order by ri.id;
select tipo,detalhes::text Detalhes,ocorrido_em OcorridoEm from sigov.compras_empresarial_recebimento_evento where tenant_id=@t and recebimento_id=@id order by ocorrido_em,id";
